<style>.campus-search{margin:0 0 24px}.campus-search input{width:100%;min-height:58px;font-size:18px;padding:16px;border:1px solid var(--line);border-radius:8px;background:white}.campus-search form{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px}.campus-results{display:grid;gap:12px}.campus-result{padding:16px;border:1px solid var(--line);border-radius:7px;background:white}.ops-task{border:1px solid var(--line);border-radius:8px;padding:20px;margin:18px 0;overflow-wrap:anywhere}.ops-task h3{font:24px Georgia,serif!important}.ops-summary{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.ops-summary p{margin:3px 0}.ops-check{display:flex;gap:10px;align-items:center;min-height:44px}.ops-check input{width:22px;height:22px;accent-color:#315b43}.ops-check-row{display:grid;grid-template-columns:minmax(0,1fr) 85px;gap:10px}.ops-check-row input{min-width:0}.ops-task progress{width:100%;accent-color:#315b43}.ops-task details{padding:12px 0;border-top:1px solid var(--line);margin-top:12px}.ops-task summary{min-height:44px;cursor:pointer;padding:10px 0}.ops-workspace{display:grid;grid-template-columns:1fr 1fr;gap:20px}.ops-empty{padding:20px;border:1px dashed var(--line);border-radius:7px}.ops-list{display:grid;gap:14px}.ops-list article{padding:18px;border:1px solid var(--line);border-radius:8px;background:white}.ops-list h3{margin:0 0 10px;font:23px Georgia,serif}.ops-public-update{border-top:1px solid var(--line);margin-top:18px;padding-top:18px}.ops-privacy{background:#eef2e8;border-radius:6px;padding:12px;font-size:12px;line-height:1.8}@media(max-width:900px){.ops-workspace{grid-template-columns:1fr}}@media(max-width:650px){.campus-search form{grid-template-columns:1fr}.campus-search input{font-size:16px}.ops-summary{grid-template-columns:1fr}.ops-task{padding:16px}.ops-check-row{grid-template-columns:minmax(0,1fr) 75px}}
</style>
<button class="button" id="operations-retry" type="button" hidden>Retry the same retained work change</button>
<section class="campus-search" id="campus-search" hidden aria-label="Campus search"><form id="campus-search-form"><label><span class="eyebrow">Find the right place, work or person</span><input type="search" id="campus-search-query" maxlength="150" required placeholder="Search campus buildings, requests, projects, tasks and people"></label><button class="button primary" type="submit">Search campus</button></form><p class="caption" id="campus-search-coverage"></p><div class="campus-results" id="campus-search-results" aria-live="polite"></div></section>
<section class="next-panel" id="operations-people" hidden><h2>People &amp; contractors</h2><p class="subtle">Employee membership, department access, work assignments and external contacts remain separate.</p><div class="ops-workspace"><section class="panel"><h3>Eligible assignment editors</h3><p class="caption">Current active editors eligible for assignment. This is not the complete department membership roster.</p><div id="operations-members"></div></section><section class="panel"><h3>Contractor contacts</h3><div id="operations-contractors"></div><p class="caption">Quality reviews are manager-only and separate from work completion.</p><button class="button" id="operations-plan-open" type="button">Manage contractor and cost planning</button></section></div><div id="operations-quality" class="panel" hidden></div></section>
<section class="next-panel" id="operations-workflows" hidden><h2>Operational workflows</h2><p class="subtle">Choose a project to open its complete canvas, screens, forms, run history and settings.</p><div id="operations-workflow-projects" class="ops-list"></div></section>
<section class="next-panel" id="requester-portal" hidden><h2>My service requests</h2><p class="subtle">Submit to a published department, then follow your own progress and public updates.</p><p class="ops-privacy">This view does not grant department access or show internal notes. Progress notifications here are in-app; no email or SMS is sent.</p><div class="ops-workspace"><form id="requester-form" class="panel stack"><h3>Request a service</h3><label>Department<select id="requester-department" required></select></label><label>Category<select id="requester-category"><option>IT</option><option>Events</option><option>Maintenance</option><option>Projects</option></select></label><label>Request title<input id="requester-title" maxlength="100" required></label><label>What do you need?<textarea id="requester-description" maxlength="5000" rows="5" required></textarea></label><label>Location, if known<input id="requester-location" maxlength="200"></label><button class="button primary" type="submit" id="requester-submit">Submit service request</button><p class="caption" id="requester-coverage"></p></form><section class="panel"><h3>Your requests</h3><div id="requester-list" class="ops-list"></div><article id="requester-detail"></article></section></div></section>
<details class="panel" id="workspace-preferences" hidden><summary>Workspace layout &amp; intake</summary><p class="caption" id="workspace-license"></p><div id="workspace-favorites" class="actions"></div><form id="preferences-form" class="stack"><div class="field-pair"><label>Applies to<select id="preferences-scope"><option value="personal">My layout</option><option value="workspace">Workspace defaults (manager)</option></select></label><label>Workspace default group<select id="preferences-role" disabled><option value="all">All permitted roles</option><option value="employee">Employees</option><option value="manager">Managers</option><option value="viewer">Read-only viewers</option></select></label></div><div class="field-pair"><label>Density<select id="preferences-density"><option value="comfortable">Comfortable</option><option value="compact">Compact</option></select></label><label>Preferred work view<select id="preferences-view"><option value="list">List</option><option value="calendar">Calendar</option><option value="map">Map</option></select></label></div><label>Saved work filter<select id="preferences-filter"><option value="all">All authorized work</option><option value="active">Active work</option><option value="completed">Completed work</option><option value="mine">My work</option></select></label><label><input type="checkbox" id="preferences-intake"> Publish department service intake (workspace managers only)</label><button class="button" type="submit">Save layout settings</button></form></details>
<style>[data-workspace-density=compact] .table-wrap td,[data-workspace-density=compact] .table-wrap th{padding-top:8px;padding-bottom:8px}[data-workspace-density=compact] .ops-list article{padding:12px}</style>
@includeIf('enterprise.resources-panels')
